// Process Control Block (PCB) State Storage
typedef struct {
    uintptr_t SP;              // Stack Pointer
    uintptr_t PC;              // Program Counter
    uint64_t GPR[16];          // General Purpose Registers
    void* page_table_base;     // Memory Context (MMU)
} CPU_State;

typedef struct {
    int pid;
    CPU_State state;
} PCB;

// Kernel Context Switch Logic (Minimal implementation)
void kernel_switch(PCB* old_p, PCB* new_p) {
    // 1. Save old state (registers, stack pointer)
    asm_save_state(&old_p->state);

    // 2. Update scheduler tracking (Conceptual)

    // 3. Load Memory Context (TLB flush/Page Table Base update)
    mmu_load_pt(new_p->page_table_base);

    // 4. Restore new state (jump to new PC/SP)
    asm_restore_state(&new_p->state);
}
